package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored sheets. A sheet never changed has no row and reads as starting on the real date. */
@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Sheet find(String id) {
        return new Sheet(id, today(id));
    }

    /**
     * The sheet's today. Use this — never {@code LocalDate.now()} — for every decision or default
     * that depends on the date.
     */
    public LocalDate today(String id) {
        List<LocalDate> found = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, n) -> rs.getObject(1, LocalDate.class), id);
        return found.isEmpty() ? LocalDate.now() : found.get(0);
    }

    public void saveToday(String id, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", id, today);
    }
}
# PUT /api/sheets/{sheetId}/claims/{claimId}/status — change a claim's status by an action: open
# (DRAFT to OPEN), settle (OPEN to SETTLED) or void (DRAFT or OPEN to VOID). An action the claim's
# status does not allow, a claim dated inside a closed period, settling by the user who opened the claim, a
# clerk settling a claim whose due is above the sheet's clerk limit, or an unknown action, is a 409
# and a claim not on the sheet a 404, neither writing anything. Opening gives the claim the sheet's
# next number and records who opened it; a voided claim keeps its number. Responds with the claim as
# stored.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimStatus
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimStatus
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimStatusChanged
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
# POST /api/sheets/{sheetId}/bulk-open — open the selected claims together. Each selected claim that can be opened
# (a DRAFT not dated inside a closed period) is opened as the single open does, in list order: people in the order
# they were added, a person's claims newest first, so each takes the sheet's next number in that order and writes
# its own CLAIM_OPENED, ROLLUP and TOTALS lines. Each that cannot (or is not on the sheet) is left as it is and
# counted refused. Responds with how many were opened and how many refused.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkOpen
  next: open
open:
  class: net.officefloor.hq.app.claim.OpenClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen

